// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  /**
   * AIChunk is sent with the text an AI writing request streams, and once
   * more when it ends.
   */
  aiChunk: event<AIChunkEvent>("aiChunk"),
  /** BoardChanged is sent with all the board's data whenever it changes. */
  boardChanged: event<BoardData>("boardChanged"),
  /** ClipsChanged is sent with the clipboard history whenever it changes. */
  clipsChanged: event<ClipItem[]>("clipsChanged"),
  /** ClipsSummoned tells the history's popup that the shortcut brought it up. */
  clipsSummoned: event<number>("clipsSummoned"),
  /**
   * DevQRFound is sent with what a QR code cut out of the screen says, for
   * the dev tools' page.
   */
  devQRFound: event<DevQRResult>("devQRFound"),
  /** FlowChanged is sent with the pipelines whenever they are fetched. */
  flowChanged: event<FlowState>("flowChanged"),
  /** FlowFocus asks the tool's page to show a run, as the bubble's 看日志. */
  flowFocus: event<string>("flowFocus"),
  /**
   * ImageEditOpened tells the image editor's page that a picture waits for
   * it, as a screenshot sent to 编辑: the page takes it with Take.
   */
  imageEditOpened: event<number>("imageEditOpened"),
  /**
   * LauncherChanged is sent with the new data whenever the apps or the
   * categories change.
   */
  launcherChanged: event<LauncherData>("launcherChanged"),
  /** LauncherSummoned is sent when the shortcut brings the launcher up. */
  launcherSummoned: event<boolean>("launcherSummoned"),
  /**
   * MonitorSampled is sent with every sample while the monitor page or the
   * overlay watches.
   */
  monitorSampled: event<MonitorSample>("monitorSampled"),
  /**
   * NotesChanged is sent with the new data whenever a todo or a note
   * changes.
   */
  notesChanged: event<NotesData>("notesChanged"),
  /**
   * TodoAlertsChanged is sent with the ringing todos after every change, to
   * the small windows: the floating ball and the reminder bubble have no
   * use for the notes.
   */
  todoAlertsChanged: event<Todo[]>("todoAlertsChanged"),
  /** PetChatOpened tells the chat's page it came up, to take the keys. */
  petChatOpened: event<number>("petChatOpened"),
  /**
   * RecordChanged tells the recording's panel, and the tool's page, what
   * the recording is doing.
   */
  recordChanged: event<RecordState>("recordChanged"),
  /** ScrollShotChanged tells the long screenshot's panel how far it got. */
  scrollShotChanged: event<ScrollShotState>("scrollShotChanged"),
  /**
   * ServicesChanged is sent with the services and their states whenever a
   * check ends or the list changes.
   */
  servicesChanged: event<ServiceView[]>("servicesChanged"),
  /** SettingsChanged is sent with the new settings whenever they change. */
  settingsChanged: event<AppSettings>("settingsChanged"),
  /** ShotCaptured tells the selection windows that a new screenshot waits. */
  shotCaptured: event<number>("shotCaptured"),
  /**
   * ShotEnded tells the selection windows, hidden now, to let go of the
   * screenshot: a whole screen's picture each, decoded, and its canvas.
   */
  shotEnded: event<number>("shotEnded"),
  /**
   * PinAction asks a pinned picture's page, from its menu, to recognize or
   * translate its text.
   */
  pinAction: event<PinActionEvent>("pinAction"),
  /** UpdateChanged is sent whenever a check or a download moves on. */
  updateChanged: event<UpdateState>("updateChanged"),
  /** VirtualScreenChanged is sent whenever the virtual screen turns on or off. */
  virtualScreenChanged: event<boolean>("virtualScreenChanged"),
  /**
   * VirtualScreenFailed is sent with the reason when the shortcut, the tray
   * or the floating ball could not turn the virtual screen on.
   */
  virtualScreenFailed: event<string>("virtualScreenFailed"),
  /** ShowTool asks the toolbox's page to show a tool. */
  showTool: event<string>("showTool"),
} as const;
